window.DATA = {"cards":[{"id":"c000","term":"Nursing Process","def":"Assess, Diagnose, Plan, Implement, Evaluate (ADPIE). The systematic framework for clinical decision-making. Assessment always comes first.","cat":"Safe Care"},{"id":"c001","term":"Priority Setting: ABCs","def":"Airway, Breathing, Circulation. The first priority framework — a compromised airway takes precedence over everything except active hemorrhage.","cat":"Safe Care"},{"id":"c002","term":"Priority Setting: Maslow","def":"Physiological needs first, then safety, love/belonging, esteem, self-actualization. Applied after ABCs — a hungry patient's education can wait.","cat":"Safe Care"},{"id":"c003","term":"Acute vs. Chronic Priority","def":"Acute and unstable conditions take priority over chronic and stable ones. A new-onset symptom outranks a longstanding one.","cat":"Safe Care"},{"id":"c004","term":"Delegation","def":"Transferring responsibility for a task while retaining accountability for the outcome. The RN delegates, but cannot delegate assessment, teaching, evaluation, or nursing judgment.","cat":"Safe Care"},{"id":"c005","term":"Five Rights of Delegation","def":"Right task, right circumstance, right person, right direction/communication, right supervision/evaluation.","cat":"Safe Care"},{"id":"c006","term":"Scope of Practice: RN vs. LPN vs. UAP","def":"RN: assessment, care planning, teaching, evaluation, unstable patients. LPN: data collection, stable/predictable care, medication administration. UAP: ADLs, vital signs, I&O, ambulation.","cat":"Safe Care"},{"id":"c007","term":"Assignment vs. Delegation","def":"Assignment: distributing work among licensed staff within their scope. Delegation: transferring a task to someone not normally authorized to perform it.","cat":"Safe Care"},{"id":"c008","term":"Informed Consent","def":"Voluntary agreement after disclosure of procedure, risks, benefits, alternatives, and right to refuse. The physician obtains it; the nurse witnesses and ensures understanding.","cat":"Safe Care"},{"id":"c009","term":"Advance Directives","def":"Living will and healthcare proxy/durable power of attorney. Document treatment preferences before incapacity. The nurse ensures they are in the chart and honored.","cat":"Safe Care"},{"id":"c010","term":"HIPAA","def":"Federal law protecting patient health information. Minimum necessary standard — share only what is needed for care. Violations include looking at charts of non-assigned patients.","cat":"Safe Care"},{"id":"c011","term":"Mandatory Reporting","def":"Nurses must report suspected abuse (child, elder, domestic), communicable diseases, impaired colleagues, and unsafe staffing. Failure to report is a legal violation.","cat":"Safe Care"},{"id":"c012","term":"Incident Report","def":"Documents unexpected events (falls, medication errors, near-misses). Completed for risk management, not placed in the patient chart. Factual, no blame.","cat":"Safe Care"},{"id":"c013","term":"Chain of Command","def":"When a concern is not addressed, escalate: charge nurse → nurse manager → supervisor → chief nursing officer. Document each step.","cat":"Safe Care"},{"id":"c014","term":"Restraint Use","def":"Last resort after all alternatives fail. Requires a physician order within 1 hour of application. Assess circulation, sensation, and movement every 2 hours. Release every 2 hours.","cat":"Safe Care"},{"id":"c015","term":"Fall Prevention","def":"Risk assessment (Morse Fall Scale), bed alarm, call light within reach, non-skid footwear, toileting schedule, low bed position, adequate lighting.","cat":"Safe Care"},{"id":"c016","term":"Standard Precautions","def":"Applied to ALL patients regardless of diagnosis: hand hygiene, gloves for body fluids, mask/eye protection for splashes, safe sharps disposal.","cat":"Safe Care"},{"id":"c017","term":"Transmission-Based Precautions","def":"Contact (gown + gloves: MRSA, C. diff, scabies). Droplet (surgical mask: flu, pertussis, meningococcal). Airborne (N95 + negative pressure: TB, measles, varicella, COVID).","cat":"Safe Care"},{"id":"c018","term":"Hand Hygiene","def":"The single most effective intervention to prevent healthcare-associated infections. Soap and water for C. diff and visibly soiled hands; alcohol-based rub otherwise.","cat":"Safe Care"},{"id":"c019","term":"Sterile Technique","def":"Used for surgical wounds, urinary catheterization, IV insertion. A 1-inch border around a sterile field is considered contaminated. Wet = contaminated. Below waist = contaminated.","cat":"Safe Care"},{"id":"c020","term":"Surgical Safety Checklist","def":"Time-out before incision: correct patient, correct site, correct procedure, consents signed, allergies reviewed, antibiotics given.","cat":"Safe Care"},{"id":"c021","term":"Medication Rights","def":"Right patient, right drug, right dose, right route, right time, right documentation, right reason, right response, right to refuse.","cat":"Safe Care"},{"id":"c022","term":"High-Alert Medications","def":"Medications with high risk for harm if used in error: insulin, heparin, warfarin, opioids, potassium chloride, chemotherapy. Require independent double-checks.","cat":"Safe Care"},{"id":"c023","term":"Look-Alike/Sound-Alike Drugs","def":"Medications with similar names or packaging (e.g., hydroxyzine/hydralazine, metformin/metronidazole). Use tall-man lettering and independent verification.","cat":"Safe Care"},{"id":"c024","term":"Medication Reconciliation","def":"Comparing the patient's current medications against orders at every transition of care: admission, transfer, and discharge.","cat":"Safe Care"},{"id":"c025","term":"SBAR Communication","def":"Situation, Background, Assessment, Recommendation. Structured handoff framework that reduces communication errors between providers.","cat":"Safe Care"},{"id":"c026","term":"Quality Improvement","def":"Systematic approach to analyzing and improving care processes. Plan-Do-Study-Act (PDSA) cycle. Root cause analysis after sentinel events.","cat":"Safe Care"},{"id":"c027","term":"Sentinel Event","def":"An unexpected occurrence involving death or serious physical or psychological injury. Triggers root cause analysis and corrective action.","cat":"Safe Care"},{"id":"c028","term":"Evidence-Based Practice","def":"Integrating best research evidence, clinical expertise, and patient preferences. Asking a clinical question → searching → appraising → applying → evaluating.","cat":"Safe Care"},{"id":"c029","term":"Growth and Development Milestones","def":"Key markers: social smile (2mo), sits unsupported (6mo), walks (12mo), 2-word phrases (2yr), rides tricycle (3yr), ties shoes (5yr). Deviations warrant further assessment.","cat":"Health Promo"},{"id":"c030","term":"Immunization Schedule","def":"Follow CDC schedule. Live vaccines (MMR, varicella) contraindicated in pregnancy and immunocompromised. Fever is NOT a contraindication. Anaphylaxis to a component IS.","cat":"Health Promo"},{"id":"c031","term":"Prenatal Care","def":"Visits: monthly until 28 weeks, biweekly until 36, then weekly. Monitor weight, BP, fundal height, fetal heart tones. Screen for gestational diabetes at 24–28 weeks.","cat":"Health Promo"},{"id":"c032","term":"Prenatal Danger Signs","def":"Vaginal bleeding, severe headache, visual changes, epigastric pain, facial edema, decreased fetal movement, fluid gush. Report immediately.","cat":"Health Promo"},{"id":"c033","term":"Stages of Labor","def":"Stage 1: onset to full dilation (latent, active, transition). Stage 2: full dilation to delivery. Stage 3: delivery of placenta. Stage 4: first 1–2 hours postpartum (recovery).","cat":"Health Promo"},{"id":"c034","term":"Postpartum Assessment","def":"BUBBLE-HE: Breasts, Uterus (firm, midline, descending), Bladder, Bowel, Lochia (rubra→serosa→alba), Episiotomy/incision, Homan's sign, Emotional status.","cat":"Health Promo"},{"id":"c035","term":"Newborn Assessment","def":"APGAR at 1 and 5 minutes (Appearance, Pulse, Grimace, Activity, Respirations). Vitamin K IM, erythromycin eye ointment, hepatitis B vaccine within 12 hours.","cat":"Health Promo"},{"id":"c036","term":"Breastfeeding","def":"Initiate within 1 hour of birth. Colostrum provides antibodies. Feed on demand (8–12 times/day). Assess latch, swallowing, wet diapers (6+/day by day 4).","cat":"Health Promo"},{"id":"c037","term":"Screening Tests","def":"Cancer screenings per guidelines: mammography, colonoscopy, Pap smear, PSA (discuss). Also: cholesterol, diabetes, depression, substance use, STIs based on risk.","cat":"Health Promo"},{"id":"c038","term":"Health Teaching Principles","def":"Assess readiness to learn, literacy level, cultural factors, and barriers. Use teach-back method. Keep instructions at 5th–6th grade reading level.","cat":"Health Promo"},{"id":"c039","term":"Aging Changes","def":"Decreased cardiac output, reduced renal clearance (affects drug dosing), decreased bone density, reduced visual/hearing acuity, slowed metabolism, thinning skin.","cat":"Health Promo"},{"id":"c040","term":"Pediatric Safety","def":"Rear-facing car seat until age 2, no honey before age 1, no small objects (choking), water safety, firearm safety, helmet use, sun protection.","cat":"Health Promo"},{"id":"c041","term":"Adolescent Health","def":"Screen for depression, substance use, sexual activity, eating disorders, bullying. Confidentiality with limits. Anticipatory guidance on risk behaviors.","cat":"Health Promo"},{"id":"c042","term":"Therapeutic Communication","def":"Open-ended questions, reflection, restating, silence, summarizing, validation. Non-therapeutic: false reassurance, giving advice, changing the subject, asking 'why.'","cat":"Psychosocial"},{"id":"c043","term":"Anxiety Levels","def":"Mild (heightened awareness), moderate (narrowed focus), severe (scattered, physical symptoms), panic (loss of rational thought, fight/flight). Interventions match the level.","cat":"Psychosocial"},{"id":"c044","term":"Crisis Intervention (Nursing)","def":"Brief, directive, present-focused. Establish safety, identify the precipitating event, assess coping resources, develop a plan. Goal: return to at least pre-crisis function.","cat":"Psychosocial"},{"id":"c045","term":"Suicide Assessment","def":"Ask directly: ideation, plan, means, intent, timeline. Risk factors: prior attempt, substance use, isolation, hopelessness, giving away possessions, sudden calm. Never leave the patient alone.","cat":"Psychosocial"},{"id":"c046","term":"Suicide Precautions","def":"One-to-one observation, remove harmful objects (sharps, belts, cords, glass), check belongings, monitor during high-risk times (shift change, nights), document every 15 minutes.","cat":"Psychosocial"},{"id":"c047","term":"Depression Nursing Care","def":"Safety first (suicide risk highest as energy returns). Structure activities, encourage social interaction, monitor eating/sleeping, medication education (SSRIs take 4–6 weeks).","cat":"Psychosocial"},{"id":"c048","term":"Bipolar: Mania Nursing Care","def":"Decrease stimulation, set firm limits, redirect, high-calorie finger foods (won't sit to eat), monitor lithium levels (0.6–1.2 mEq/L therapeutic, >1.5 toxic).","cat":"Psychosocial"},{"id":"c049","term":"Schizophrenia Nursing Care","def":"Build trust slowly, don't argue with delusions, focus on feelings behind hallucinations, maintain safety, monitor medication adherence, watch for EPS/tardive dyskinesia.","cat":"Psychosocial"},{"id":"c050","term":"Substance Withdrawal","def":"Alcohol: tremors → seizures → delirium tremens (medical emergency, 48–72 hr). Opioid: flu-like, not life-threatening. Benzodiazepine: can be fatal, taper required.","cat":"Psychosocial"},{"id":"c051","term":"Defense Mechanisms","def":"Denial, projection, displacement, regression, rationalization, sublimation, reaction formation, suppression. Unconscious strategies reducing anxiety.","cat":"Psychosocial"},{"id":"c052","term":"Grief and Loss","def":"Kübler-Ross stages (not linear): denial, anger, bargaining, depression, acceptance. Nursing role: presence, active listening, normalizing grief. Do not rush stages.","cat":"Psychosocial"},{"id":"c053","term":"Abuse Assessment","def":"Screen all patients. Signs: unexplained injuries, inconsistent history, withdrawal, fearful of partner. Safety plan before discharge. Report per mandated reporting laws.","cat":"Psychosocial"},{"id":"c054","term":"Eating Disorders","def":"Anorexia: monitor for refeeding syndrome (electrolyte shifts, cardiac arrest). Bulimia: assess for esophageal tears, dental erosion, hypokalemia. Both: therapeutic relationship first.","cat":"Psychosocial"},{"id":"c055","term":"Milieu Therapy","def":"Structured, safe environment as a therapeutic tool. Clear rules, predictable routine, group activities, patient participation in treatment planning.","cat":"Psychosocial"},{"id":"c056","term":"Restraint Alternatives","def":"De-escalation, 1:1 interaction, diversion activities, PRN medication, environmental modification. Document that alternatives were tried before restraints.","cat":"Psychosocial"},{"id":"c057","term":"Pain Assessment","def":"Use appropriate scale (numeric, FACES, FLACC for nonverbal). Pain is what the patient says it is. Reassess after intervention. Document.","cat":"Basic Care"},{"id":"c058","term":"Non-Pharmacological Pain Management","def":"Repositioning, heat/cold, massage, distraction, guided imagery, relaxation breathing, music therapy, TENS. Use alongside medication, not as a replacement when pain is significant.","cat":"Basic Care"},{"id":"c059","term":"Nutrition Assessment","def":"BMI, albumin/prealbumin (protein status), weight changes, skin turgor, dietary history. Malnourished: albumin < 3.5, prealbumin < 15. Assess swallowing before feeding post-stroke.","cat":"Basic Care"},{"id":"c060","term":"Therapeutic Diets","def":"Low sodium (heart failure, HTN), renal diet (low K+, low phosphorus, fluid restriction), diabetic (consistent carbs), clear liquid → full liquid → soft → regular (post-op progression).","cat":"Basic Care"},{"id":"c061","term":"Enteral Nutrition","def":"Tube feeding: verify placement (X-ray gold standard, pH < 5.5), elevate HOB 30–45°, check residual, flush with water. Hold if residual > 250–500 mL per policy.","cat":"Basic Care"},{"id":"c062","term":"Fluid Balance","def":"Intake and output monitoring. Signs of dehydration: tachycardia, hypotension, poor turgor, concentrated urine. Overload: edema, crackles, JVD, weight gain (1 L = 1 kg).","cat":"Basic Care"},{"id":"c063","term":"Skin Integrity","def":"Pressure injury prevention: reposition every 2 hours, moisture barrier, nutrition optimization, pressure-relieving surfaces. Braden Scale for risk assessment.","cat":"Basic Care"},{"id":"c064","term":"Mobility and Ambulation","def":"ROM exercises, progressive ambulation, use of assistive devices. Assess for orthostatic hypotension before first ambulation. Fall precautions for at-risk patients.","cat":"Basic Care"},{"id":"c065","term":"Elimination","def":"Urinary: assess for retention (bladder scan > 300 mL), catheter care. Bowel: document frequency, consistency (Bristol scale), assess for impaction in immobile patients.","cat":"Basic Care"},{"id":"c066","term":"Sleep and Rest","def":"Assess sleep patterns and disturbances. Non-pharmacological first: consistent schedule, reduced stimuli, warm bath, limit caffeine. Sedatives as last resort in elderly (fall risk).","cat":"Basic Care"},{"id":"c067","term":"Pharmacokinetics","def":"Absorption (route-dependent), Distribution (protein binding), Metabolism (primarily liver, CYP450), Excretion (primarily renal). Impaired liver/kidney = dose adjustment.","cat":"Pharmacology"},{"id":"c068","term":"Drug Interactions","def":"Additive (same effect doubled), synergistic (combined effect > sum), antagonistic (one blocks another). Grapefruit inhibits CYP3A4. Warfarin interacts with everything.","cat":"Pharmacology"},{"id":"c069","term":"Antihypertensives","def":"ACE inhibitors (-pril): dry cough, hyperkalemia, monitor renal. ARBs (-sartan): similar without cough. Beta-blockers (-olol): bradycardia, mask hypoglycemia. CCBs (-dipine): peripheral edema.","cat":"Pharmacology"},{"id":"c070","term":"Diuretics","def":"Loop (furosemide): potent, monitor K+, ototoxicity. Thiazide (HCTZ): moderate, monitor K+. Potassium-sparing (spironolactone): hyperkalemia risk. Weigh daily, monitor electrolytes.","cat":"Pharmacology"},{"id":"c071","term":"Anticoagulants","def":"Heparin: IV, monitor aPTT (1.5–2.5× control), antidote protamine sulfate. Warfarin: PO, monitor INR (2–3), antidote vitamin K. DOACs (rivaroxaban): no routine monitoring.","cat":"Pharmacology"},{"id":"c072","term":"Insulin","def":"Rapid (lispro): onset 15 min, give with meals. Regular: onset 30 min. NPH: intermediate, cloudy, do not mix with long-acting. Long-acting (glargine): once daily, clear, never mix.","cat":"Pharmacology"},{"id":"c073","term":"Oral Hypoglycemics","def":"Metformin: first-line for type 2, hold before contrast dye, risk of lactic acidosis. Sulfonylureas (glipizide): risk of hypoglycemia. Monitor renal function.","cat":"Pharmacology"},{"id":"c074","term":"Cardiac Glycosides","def":"Digoxin: slows heart rate, increases contractility. Therapeutic range 0.5–2.0 ng/mL. Hold if HR < 60. Monitor potassium (hypokalemia increases toxicity). Antidote: Digibind.","cat":"Pharmacology"},{"id":"c075","term":"Opioid Analgesics","def":"Morphine, hydrocodone, oxycodone, fentanyl. Monitor respiratory rate (hold if < 12). Constipation prevention. Naloxone (Narcan) is the antidote. Assess pain before and after.","cat":"Pharmacology"},{"id":"c076","term":"Antibiotics","def":"Assess for allergies (penicillin cross-reacts with cephalosporins). Complete full course. Monitor for C. diff (watery diarrhea). Aminoglycosides: peak/trough, nephro/ototoxicity.","cat":"Pharmacology"},{"id":"c077","term":"Corticosteroids","def":"Prednisone, dexamethasone. Immunosuppression, hyperglycemia, osteoporosis, adrenal suppression. Never stop abruptly — taper. Take with food. Monitor blood glucose.","cat":"Pharmacology"},{"id":"c078","term":"Antiepileptics","def":"Phenytoin: therapeutic 10–20 mcg/mL, gingival hyperplasia, monitor levels. Valproic acid: hepatotoxicity, teratogenic. Seizure precautions during titration.","cat":"Pharmacology"},{"id":"c079","term":"Psychotropic Medications","def":"SSRIs (4–6 weeks to effect, serotonin syndrome risk). Lithium (narrow range 0.6–1.2, toxicity: tremor, diarrhea, confusion). MAOIs (tyramine crisis — avoid aged cheese, wine).","cat":"Pharmacology"},{"id":"c080","term":"Bronchodilators","def":"Short-acting beta2 agonists (albuterol): rescue inhaler, tremor, tachycardia. Long-acting (salmeterol): maintenance, never for acute. Anticholinergics (ipratropium): dry mouth.","cat":"Pharmacology"},{"id":"c081","term":"Chemotherapy Principles","def":"Nadir: lowest point of blood counts post-treatment (neutropenia risk). Neutropenic precautions. Antiemetics before administration. Assess for tumor lysis syndrome.","cat":"Pharmacology"},{"id":"c082","term":"Lab Values: Electrolytes","def":"Na+ 136–145, K+ 3.5–5.0, Ca++ 9–10.5, Mg++ 1.5–2.5. Hypo/hyperkalemia affects cardiac rhythm. Hypocalcemia: Chvostek's and Trousseau's signs.","cat":"Physio"},{"id":"c083","term":"Lab Values: CBC","def":"WBC 5,000–10,000, Hgb 12–17, Hct 36–52%, Platelets 150,000–400,000. Elevated WBC = infection. Low platelets = bleeding risk. Low Hgb = anemia.","cat":"Physio"},{"id":"c084","term":"Lab Values: Renal","def":"BUN 10–20, Creatinine 0.6–1.2. Elevated = renal impairment. GFR < 60 for 3+ months = chronic kidney disease. Adjust renally-cleared medications.","cat":"Physio"},{"id":"c085","term":"Lab Values: Coagulation","def":"PT 11–13.5 sec, INR 2–3 (on warfarin), aPTT 60–70 sec (on heparin). Elevated = bleeding risk. Monitor for signs of bleeding.","cat":"Physio"},{"id":"c086","term":"Lab Values: Cardiac","def":"Troponin: elevated in MI (most specific). BNP: elevated in heart failure. CK-MB: elevated in MI (less specific than troponin).","cat":"Physio"},{"id":"c087","term":"ABG Interpretation","def":"pH 7.35–7.45, PaCO2 35–45, HCO3 22–26. Acidosis < 7.35, alkalosis > 7.45. Respiratory: CO2 driven. Metabolic: HCO3 driven. Compensation moves the other value.","cat":"Physio"},{"id":"c088","term":"Respiratory Acidosis","def":"pH < 7.35, PaCO2 > 45. Cause: hypoventilation (COPD, oversedation, neuromuscular disease). Intervention: improve ventilation, hold sedatives.","cat":"Physio"},{"id":"c089","term":"Metabolic Acidosis","def":"pH < 7.35, HCO3 < 22. Causes: DKA, renal failure, diarrhea, lactic acidosis. Kussmaul breathing (compensatory). Treat the underlying cause.","cat":"Physio"},{"id":"c090","term":"Respiratory Alkalosis","def":"pH > 7.45, PaCO2 < 35. Cause: hyperventilation (anxiety, pain, fever, PE). Intervention: address cause, paper bag for anxiety-driven.","cat":"Physio"},{"id":"c091","term":"Metabolic Alkalosis","def":"pH > 7.45, HCO3 > 26. Causes: vomiting, NG suction, diuretics, antacid overuse. Replace chloride and potassium.","cat":"Physio"},{"id":"c092","term":"Heart Failure","def":"Left-sided: pulmonary congestion (crackles, dyspnea, orthopnea, pink frothy sputum). Right-sided: systemic congestion (JVD, peripheral edema, hepatomegaly, weight gain).","cat":"Physio"},{"id":"c093","term":"Myocardial Infarction","def":"Chest pain, diaphoresis, nausea, jaw/arm pain. MONA (Morphine, Oxygen if needed, Nitroglycerin, Aspirin). 12-lead ECG within 10 minutes. Troponin levels. Time = muscle.","cat":"Physio"},{"id":"c094","term":"Stroke","def":"FAST: Face drooping, Arm weakness, Speech difficulty, Time to call 911. Ischemic (85%): tPA within 3–4.5 hours. Hemorrhagic: manage BP, no anticoagulants. CT first to differentiate.","cat":"Physio"},{"id":"c095","term":"Diabetes: DKA vs. HHS","def":"DKA (Type 1): rapid onset, Kussmaul breathing, fruity breath, pH < 7.3, glucose 300–800. HHS (Type 2): gradual, no ketosis, glucose > 600, severe dehydration. Both: fluids + insulin.","cat":"Physio"},{"id":"c096","term":"Diabetes Management","def":"Monitor blood glucose, A1C (goal < 7%), foot care, eye exams, carb counting, sick day rules, hypoglycemia treatment (rule of 15: 15g fast carbs, recheck in 15 min).","cat":"Physio"},{"id":"c097","term":"Hypoglycemia vs. Hyperglycemia","def":"Hypo: tremor, sweating, confusion, tachycardia, irritability (treat immediately with glucose). Hyper: polyuria, polydipsia, polyphagia, blurred vision, fruity breath if DKA.","cat":"Physio"},{"id":"c098","term":"Asthma vs. COPD","def":"Asthma: reversible, triggered, wheezing, responds to bronchodilators. COPD: progressive, barrel chest, pursed-lip breathing, O2 at 1–2 L (hypoxic drive). Both: inhaler technique.","cat":"Physio"},{"id":"c099","term":"Pneumonia","def":"Productive cough, fever, crackles, dyspnea, elevated WBC. Nursing: incentive spirometry, position for drainage, O2, antibiotics, hydration. Prevent aspiration.","cat":"Physio"},{"id":"c100","term":"Renal Failure","def":"Acute: sudden onset, often reversible (prerenal, intrarenal, postrenal). Chronic: progressive, irreversible. Monitor I&O, daily weight, electrolytes (K+!), fluid restriction, dialysis access.","cat":"Physio"},{"id":"c101","term":"Dialysis Nursing Care","def":"Hemodialysis: AV fistula/graft — no BP, no venipuncture on access arm, assess for thrill/bruit. Peritoneal: sterile technique, monitor for cloudy effluent (peritonitis).","cat":"Physio"},{"id":"c102","term":"Thyroid Disorders","def":"Hypo: fatigue, weight gain, cold intolerance, constipation, bradycardia. Hyper: weight loss, heat intolerance, tachycardia, exophthalmos. Thyroid storm: medical emergency.","cat":"Physio"},{"id":"c103","term":"Seizure Precautions","def":"Padded side rails, suction at bedside, O2 available, IV access. During seizure: protect head, do not restrain, do not put anything in mouth, time the seizure, turn to side after.","cat":"Physio"},{"id":"c104","term":"Shock","def":"Hypovolemic: hemorrhage/dehydration. Cardiogenic: pump failure. Distributive: septic/anaphylactic/neurogenic. Signs: tachycardia, hypotension, altered LOC, decreased urine output. Treat cause + fluids.","cat":"Physio"},{"id":"c105","term":"Burns","def":"Rule of 9s for BSA. Airway first. Fluid resuscitation (Parkland formula). Wound care. Monitor for compartment syndrome, infection, fluid shifts. Assess urine output (30 mL/hr minimum).","cat":"Physio"},{"id":"c106","term":"Post-Operative Care","def":"Assess ABCs, LOC, vital signs, surgical site, drains, I&O. Incentive spirometry, early ambulation, pain management, DVT prophylaxis. Report unexpected changes immediately.","cat":"Physio"},{"id":"c107","term":"Chest Tube Management","def":"Keep drainage system below chest level. Tidaling is normal. Continuous bubbling in water seal = air leak. Never clamp without order. If disconnected: place end in sterile water.","cat":"Physio"},{"id":"c108","term":"Blood Transfusion","def":"Verify with two nurses: patient ID, blood type, expiration. Start slowly (first 15 min). Monitor for reaction: fever, chills, hives, back pain, dyspnea. Stop transfusion first, then NS, then notify.","cat":"Physio"},{"id":"c109","term":"Tracheostomy Care","def":"Keep obturator and spare trach at bedside. Suction PRN (hyperoxygenate before). Clean inner cannula. Assess stoma. Ties secure with one finger underneath. Humidification.","cat":"Physio"},{"id":"c110","term":"Central Line Care","def":"Sterile dressing change per protocol. Assess insertion site for redness, drainage. Flush per protocol. Monitor for air embolism (clamp, left Trendelenburg). CLABSI prevention bundle.","cat":"Physio"},{"id":"c111","term":"Wound Care","def":"Assess: size, depth, drainage (serous, sanguineous, purulent), odor, surrounding tissue. Clean from center outward. Moist wound healing. Document with each dressing change.","cat":"Physio"},{"id":"c112","term":"Cancer Warning Signs","def":"CAUTION: Change in bowel/bladder, A sore that doesn't heal, Unusual bleeding, Thickening/lump, Indigestion/difficulty swallowing, Obvious change in mole, Nagging cough.","cat":"Physio"},{"id":"c113","term":"Preeclampsia","def":"BP ≥ 140/90 after 20 weeks with proteinuria. Severe: BP ≥ 160/110, headache, visual changes, epigastric pain. Treatment: magnesium sulfate (monitor for toxicity: absent reflexes, respiratory depression).","cat":"Physio"},{"id":"c114","term":"Magnesium Sulfate","def":"Given for preeclampsia seizure prophylaxis and preterm labor tocolysis. Monitor: deep tendon reflexes, respiratory rate (hold if < 12), urine output, level 4–7 mEq/L. Antidote: calcium gluconate.","cat":"Physio"}],"questions":[{"cat":"Basic Care","stem":"A patient rates pain at 8/10 one hour after receiving IV morphine. The nurse should FIRST:","choices":["Apply ice to the affected area","Administer another dose immediately","Assume the patient is drug-seeking","Assess the pain characteristics and check when the next dose is due"],"answer":3,"label":"Reassess pain","why":"Reassess pain quality, location, and timing of last dose. The patient may need a dose adjustment, alternative medication, or non-pharmacological intervention.","id":"q027","n":27},{"cat":"Health Promo","stem":"A mother asks when her infant can start solid foods. The nurse advises:","choices":["At 2 months with rice cereal in the bottle","At 4–6 months when the infant can sit with support and shows interest","Whenever the infant seems hungry between feedings","At 12 months when the child has a full set of teeth"],"answer":1,"label":"Solid food introduction","why":"AAP recommends introducing solids around 4–6 months when developmental readiness cues are present, not before.","id":"q011","n":11},{"cat":"Pharmacology","stem":"A patient on warfarin has an INR of 5.2. The nurse should:","choices":["Administer the next scheduled dose as ordered","Hold the warfarin and notify the physician","Administer protamine sulfate","Double the dose to reach therapeutic range faster"],"answer":1,"label":"Supratherapeutic INR","why":"INR > 3 on standard therapy is supratherapeutic with bleeding risk. Hold the drug and notify. Protamine is for heparin, not warfarin. Vitamin K is the warfarin antidote.","id":"q032","n":32},{"cat":"Physio","stem":"A patient's ABG results show pH 7.28, PaCO2 55, HCO3 24. This indicates:","choices":["Metabolic acidosis","Respiratory acidosis","Metabolic alkalosis","Respiratory alkalosis"],"answer":1,"label":"ABG interpretation","why":"pH low (acidosis), CO2 high (respiratory cause), HCO3 normal (no compensation yet). This is uncompensated respiratory acidosis.","id":"q040","n":40},{"cat":"Psychosocial","stem":"A patient says 'I can't go on anymore. My family would be better off without me.' The nurse's BEST response is:","choices":["'Let me call the chaplain for you.'","'Don't say that — your family loves you.'","'Things will get better with time.'","'Are you thinking about hurting yourself?'"],"answer":3,"label":"Direct suicide inquiry","why":"Asking directly about suicidal thoughts does not increase risk and is essential for assessment. False reassurance and deflection avoid the issue.","id":"q019","n":19},{"cat":"Safe Care","stem":"A nurse receives orders for four patients. Which should be assessed FIRST?","choices":["Patient with diabetes and a blood glucose of 210","Patient with heart failure who gained 2 lbs overnight","Patient 1 day post-op requesting pain medication","Patient with COPD and O2 sat of 89% on 2L"],"answer":3,"label":"Airway/breathing priority","why":"ABCs: a compromised respiratory status (O2 sat 89%) takes priority over pain, an elevated but non-critical glucose, or expected fluid retention.","id":"q001","n":1},{"cat":"Basic Care","stem":"A patient with dysphagia is being started on an oral diet. The nurse should:","choices":["Allow the patient to eat in a reclined position for comfort","Encourage the patient to drink through a straw","Position the patient upright, offer thickened liquids and soft foods, and observe for coughing","Offer thin liquids first since they are easiest to swallow"],"answer":2,"label":"Dysphagia safety","why":"Upright position, thickened liquids, and soft foods reduce aspiration risk. Thin liquids and straws increase aspiration risk. Never recline during eating.","id":"q028","n":28},{"cat":"Health Promo","stem":"A pregnant client at 26 weeks reports heartburn. The nurse should recommend:","choices":["Taking a proton pump inhibitor daily","Taking an antacid before lying down for bed","Eating small frequent meals, remaining upright after eating, and avoiding spicy foods","Skipping dinner to reduce nighttime symptoms"],"answer":2,"label":"Heartburn in pregnancy","why":"Small meals, upright positioning, and trigger avoidance are first-line. Lying flat worsens reflux. Skipping meals is not appropriate.","id":"q012","n":12},{"cat":"Pharmacology","stem":"A nurse is preparing to administer digoxin. Before giving the medication, the nurse should:","choices":["Verify the patient ate breakfast","Check the patient's blood pressure","Check the patient's apical pulse for one full minute","Assess the patient's respiratory rate"],"answer":2,"label":"Digoxin pulse check","why":"Hold digoxin if apical HR < 60 (adult) or < 70 (child). Check for one full minute at the apex, not a radial pulse.","id":"q033","n":33},{"cat":"Physio","stem":"A patient with heart failure develops sudden dyspnea, pink frothy sputum, and crackles throughout lung fields. The nurse should position the patient:","choices":["On the left side in Sims' position","Flat with legs elevated","In high Fowler's position with legs dangling","In Trendelenburg position"],"answer":2,"label":"Pulmonary edema positioning","why":"High Fowler's with legs dangling reduces venous return and improves breathing in acute pulmonary edema.","id":"q041","n":41}],"meta":{"total":200,"free":10,"split":true}};
